// Webhook body -> one item per ACCEPTED row, validated before it reaches SQL.
// Expected POST body: { "batch_id": "...", "items": [ <accepted rows from wf-judge-gate> ] }
const body = $input.first().json.body || $input.first().json || {};
const items = body.items || [];
if (!Array.isArray(items) || items.length === 0) {
  throw new Error('persist-results: body.items must be a non-empty array of ACCEPTED rows');
}
const now = Date.now();
const required = ['record_id', 'chunk_id', 'classifier_version'];

return items.map((it, i) => {
  for (const k of required) {
    if (it[k] === undefined || it[k] === null || it[k] === '') {
      throw new Error('persist-results: item ' + i + ' is missing ' + k);
    }
  }
  if (it.gate_outcome && it.gate_outcome !== 'accepted') {
    throw new Error('persist-results: item ' + i + ' is not accepted (gate_outcome=' +
                    it.gate_outcome + '). needs_review rows do NOT persist here.');
  }
  return { json: {
    record_id: String(it.record_id),
    chunk_id: String(it.chunk_id),
    classifier_version: String(it.classifier_version),
    labels_json: JSON.stringify(it.labels || []),
    severity: Number(it.severity != null ? it.severity : 0),
    summary: it.summary || null,
    sentiment: it.sentiment || null,
    judge_verdict: it.judge_verdict || null,
    judge_confidence: Number(it.judge_confidence != null ? it.judge_confidence : 0),
    // TEMPORAL MANDATE: every persisted row carries when it happened, when it was labelled,
    // and when it landed. All epoch-numeric so range filters work.
    occurred_at_epoch_ms: Number(it.occurred_at_epoch_ms || 0),
    classified_at_epoch_ms: Number(it.classified_at_epoch_ms || it.judged_at_epoch_ms || now),
    persisted_at_epoch_ms: now,
    persisted_at_iso: new Date(now).toISOString(),
    batch_id: body.batch_id || it.batch_id || null,
    activity_name: 'n8n.persist.results',
  }};
});

// Activity result: what landed, under which classifier version, and when.
const rows = $input.all().map(i => i.json);
const src = $('Normalize + Validate Accepted Rows').all().map(i => i.json);
const now = Date.now();
return [{ json: {
  activity_name: 'n8n.persist.results',
  status: 'completed',
  batch_id: src.length ? src[0].batch_id : null,
  classifier_version: src.length ? src[0].classifier_version : null,
  submitted_count: src.length,
  inserted_count: rows.filter(r => r && r.record_id).length,
  skipped_existing_count: src.length - rows.filter(r => r && r.record_id).length,
  persisted_at_epoch_ms: now,
  persisted_at_iso: new Date(now).toISOString(),
  rows: rows,
}}];
